<?php
declare(strict_types=1);
session_start();
require __DIR__.'/database.php';
date_default_timezone_set('America/Sao_Paulo');
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function cfg($key,$default=''){$s=db()->prepare('SELECT setting_value FROM settings WHERE setting_key=?');$s->execute([$key]);return $s->fetchColumn()?:$default;}
function token(){return $_SESSION['public_csrf']??=bin2hex(random_bytes(32));}
function validDate($date){return preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)&&$date>=date('Y-m-d')&&$date<=date('Y-m-d',strtotime('+60 days'));}
function availableSlots(int $barberId,int $serviceId,string $date):array{
    if(!validDate($date))return [];
    $weekday=(int)date('N',strtotime($date));
    if(!in_array((string)$weekday,explode(',',cfg('work_days','1,2,3,4,5,6')),true))return [];
    $s=db()->prepare('SELECT duration FROM services WHERE id=? AND active=1');$s->execute([$serviceId]);$duration=(int)$s->fetchColumn();if(!$duration)return [];
    $s=db()->prepare('SELECT COUNT(*) FROM barbers WHERE id=? AND active=1');$s->execute([$barberId]);if(!$s->fetchColumn())return [];
    $open=strtotime("$date ".cfg('open_time','08:00'));$close=strtotime("$date ".cfg('close_time','19:00'));
    $lunchStart=strtotime("$date ".cfg('lunch_start','12:00'));$lunchEnd=strtotime("$date ".cfg('lunch_end','13:00'));$step=max(10,(int)cfg('booking_interval','30'))*60;
    $busy=db()->prepare("SELECT a.start_at,DATE_ADD(a.start_at,INTERVAL s.duration MINUTE) end_at FROM appointments a JOIN services s ON s.id=a.service_id WHERE a.barber_id=? AND DATE(a.start_at)=? AND a.status<>'Cancelado' UNION ALL SELECT start_at,end_at FROM barber_blocks WHERE barber_id=? AND DATE(start_at)<=? AND DATE(end_at)>=?");$busy->execute([$barberId,$date,$barberId,$date,$date]);$appointments=$busy->fetchAll();
    $slots=[];for($time=$open;$time+$duration*60<=$close;$time+=$step){$end=$time+$duration*60;if($time<$lunchEnd&&$end>$lunchStart)continue;if($date===date('Y-m-d')&&$time<time()+3600)continue;$free=true;foreach($appointments as $a){if($time<strtotime($a['end_at'])&&$end>strtotime($a['start_at'])){$free=false;break;}}if($free)$slots[]=date('H:i',$time);}return $slots;
}
if(cfg('public_booking_enabled','1')!=='1'){http_response_code(503);?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="booking.css"><title>Agendamento indisponível</title></head><body><main class="booking-shell"><section class="booking-brand"><div class="public-logo">✂</div><h1><?=e(cfg('business_name','BarberPro'))?></h1></section><section class="booking-card"><div class="booking-success"><h2>Agendamento online pausado</h2><p>Entre em contato com a barbearia para reservar seu horário.</p></div></section></main></body></html><?php exit;}
if(isset($_GET['ajax'])&&$_GET['ajax']==='slots'){header('Content-Type:application/json');echo json_encode(availableSlots((int)($_GET['barber_id']??0),(int)($_GET['service_id']??0),$_GET['date']??''));exit;}
$success=false;$waitlistSuccess=false;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($_SESSION['public_csrf']??'',$_POST['csrf']??''))$error='A página expirou. Atualize e tente novamente.';
    elseif(!empty($_POST['website']))$error='Não foi possível realizar o agendamento.';
    elseif(isset($_SESSION['last_public_booking'])&&time()-$_SESSION['last_public_booking']<20)$error='Aguarde alguns segundos antes de enviar novamente.';
    elseif(($_POST['action']??'')==='waitlist'){
        $name=trim($_POST['name']??'');$phone=preg_replace('/\D/','',$_POST['phone']??'');$barber=(int)($_POST['barber_id']??0);$service=(int)($_POST['service_id']??0);$date=$_POST['date']??'';
        if(mb_strlen($name)<3||strlen($phone)<10)$error='Informe seu nome e um telefone válido.';else{$q=db()->prepare("SELECT COUNT(*) FROM waitlist WHERE phone=? AND status='Aguardando'");$q->execute([$phone]);if($q->fetchColumn())$error='Seu telefone já está na lista de espera.';else{$q=db()->prepare("INSERT INTO waitlist(name,phone,service_id,barber_id,preferred_date,notes) VALUES(?,?,?,?,?,'Cadastro feito pelo cliente')");$q->execute([$name,$phone,$service?:null,$barber?:null,validDate($date)?$date:null]);$success=true;$waitlistSuccess=true;}}
    }else{
        $name=trim($_POST['name']??'');$phone=preg_replace('/\D/','',$_POST['phone']??'');$barber=(int)($_POST['barber_id']??0);$service=(int)($_POST['service_id']??0);$date=$_POST['date']??'';$time=$_POST['time']??'';
        if(mb_strlen($name)<3||strlen($phone)<10)$error='Informe seu nome e um telefone válido.';
        else{$q=db()->prepare("SELECT COUNT(*) FROM appointments a JOIN clients c ON c.id=a.client_id WHERE c.phone=? AND a.start_at>=NOW() AND a.status NOT IN('Cancelado','Concluído')");$q->execute([$phone]);$future=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(*) FROM appointments a JOIN clients c ON c.id=a.client_id WHERE c.phone=? AND DATE(a.start_at)=? AND a.status<>'Cancelado'");$q->execute([$phone,$date]);if($future>=2)$error='Você já possui dois agendamentos futuros.';elseif($q->fetchColumn())$error='Este telefone já possui um agendamento nesta data.';}
        if(!$error&&!in_array($time,availableSlots($barber,$service,$date),true))$error='Este horário não está mais disponível. Escolha outro.';
        elseif(!$error){try{db()->beginTransaction();$s=db()->prepare('SELECT duration FROM services WHERE id=? AND active=1');$s->execute([$service]);$duration=(int)$s->fetchColumn();$start="$date $time:00";$end=date('Y-m-d H:i:s',strtotime($start." +$duration minutes"));$s=db()->prepare("SELECT a.id FROM appointments a JOIN services sv ON sv.id=a.service_id WHERE a.barber_id=? AND a.status<>'Cancelado' AND a.start_at<? AND DATE_ADD(a.start_at,INTERVAL sv.duration MINUTE)>? LIMIT 1 FOR UPDATE");$s->execute([$barber,$end,$start]);if($s->fetchColumn())throw new RuntimeException('occupied');$s=db()->prepare('SELECT id FROM clients WHERE phone=? ORDER BY id LIMIT 1');$s->execute([$phone]);$clientId=(int)$s->fetchColumn();if(!$clientId){$s=db()->prepare('INSERT INTO clients(name,phone,notes) VALUES(?,?,?)');$s->execute([$name,$phone,'Cliente cadastrado pelo agendamento online']);$clientId=(int)db()->lastInsertId();}$s=db()->prepare("INSERT INTO appointments(client_id,service_id,barber_id,start_at,status,notes) VALUES(?,?,?,?,'Pendente','Agendamento realizado pelo cliente no site')");$s->execute([$clientId,$service,$barber,"$date $time:00"]);$appointmentId=(int)db()->lastInsertId();db()->prepare("INSERT INTO appointment_history(appointment_id,user_id,action,details) VALUES(?,NULL,'Solicitado pelo cliente','Agendamento online')")->execute([$appointmentId]);db()->commit();$_SESSION['last_public_booking']=time();$success=true;}catch(Throwable){if(db()->inTransaction())db()->rollBack();$error='Não foi possível concluir. Tente novamente.';}}
    }
}
$services=db()->query('SELECT id,name,price,duration FROM services WHERE active=1 ORDER BY name')->fetchAll();$barbers=db()->query('SELECT id,name FROM barbers WHERE active=1 ORDER BY name')->fetchAll();$business=cfg('business_name','BarberPro');
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Agendar horário | <?=e($business)?></title><link rel="stylesheet" href="booking.css"></head><body><main class="booking-shell"><section class="booking-brand"><div class="public-logo">✂</div><small>AGENDAMENTO ONLINE</small><h1><?=e($business)?></h1><p>Escolha o serviço, o profissional e o melhor horário. É rápido e fácil.</p><div class="trust-list"><span>✓ Horários em tempo real</span><span>✓ Confirmação pela barbearia</span><span>✓ Seus dados protegidos</span></div></section><section class="booking-card"><?php if($success):?><div class="booking-success"><div>✓</div><h2><?=$waitlistSuccess?'Você entrou na lista!':'Horário solicitado!'?></h2><p><?=$waitlistSuccess?'Avisaremos quando surgir uma vaga.':'Seu agendamento entrou na agenda da barbearia.'?></p><small><?=e(cfg('booking_notice','Seu horário será confirmado pela barbearia.'))?></small><a href="agendar.php">Fazer outro agendamento</a></div><?php else:?><div class="booking-head"><span>Reserve seu horário</span><h2>Como podemos cuidar de você?</h2></div><?php if($error):?><div class="booking-error"><?=e($error)?></div><?php endif?><form method="post" id="bookingForm"><input type="hidden" name="csrf" value="<?=token()?>"><input class="website" name="website" tabindex="-1" autocomplete="off"><label>Seu nome</label><input name="name" required value="<?=e($_POST['name']??'')?>" placeholder="Nome completo"><label>WhatsApp ou telefone</label><input name="phone" required inputmode="tel" value="<?=e($_POST['phone']??'')?>" placeholder="(00) 00000-0000"><label>Escolha o serviço</label><div class="service-options"><?php foreach($services as $s):?><button type="button" class="service-option" data-service="<?=$s['id']?>"><span><?=e($s['name'])?></span><small><b>R$ <?=number_format((float)$s['price'],2,',','.')?></b><em><?=$s['duration']?> min</em></small></button><?php endforeach?></div><select name="service_id" id="service" class="native-service" required><option value="">Escolha o serviço</option><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach?></select><div id="serviceFeedback" class="selection-feedback">Selecione um serviço acima.</div><label>Profissional</label><select name="barber_id" id="barber" required><option value="">Escolha o profissional</option><?php foreach($barbers as $b):?><option value="<?=$b['id']?>"><?=e($b['name'])?></option><?php endforeach?></select><label>Data</label><input type="date" name="date" id="date" min="<?=date('Y-m-d')?>" max="<?=date('Y-m-d',strtotime('+60 days'))?>" required><label>Horário disponível</label><div class="slots" id="slots"><p>Primeiro escolha o serviço.</p></div><input type="hidden" name="time" id="time" required><button name="action" value="booking" id="submitButton" disabled>Solicitar agendamento</button><button class="waitlist-button" name="action" value="waitlist" onclick="document.getElementById('time').required=false">Entrar na lista de espera</button><small class="booking-note">O horário ficará pendente até a confirmação da barbearia.</small></form><?php endif?></section></main><script>let service=document.getElementById('service'),barber=document.getElementById('barber'),date=document.getElementById('date'),slots=document.getElementById('slots'),time=document.getElementById('time'),submit=document.getElementById('submitButton'),feedback=document.getElementById('serviceFeedback');function waitingMessage(){if(!service.value)return'Primeiro escolha o serviço.';if(!barber.value)return'Agora escolha o profissional.';if(!date.value)return'Agora escolha a data.';return''}async function loadSlots(){time.value='';submit.disabled=true;let waiting=waitingMessage();if(waiting){slots.innerHTML='<p>'+waiting+'</p>';return}slots.innerHTML='<p>Buscando horários...</p>';try{let response=await fetch(`agendar.php?ajax=slots&service_id=${service.value}&barber_id=${barber.value}&date=${date.value}`);if(!response.ok)throw new Error();let data=await response.json();slots.innerHTML=data.length?data.map(h=>`<button type="button" data-time="${h}">${h}</button>`).join(''):'<p class="no-slots">Nenhum horário disponível nesta data.</p>';slots.querySelectorAll('button').forEach(btn=>btn.onclick=()=>{slots.querySelectorAll('button').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');time.value=btn.dataset.time;submit.disabled=false})}catch(e){slots.innerHTML='<p class="no-slots">Não foi possível carregar os horários. Tente novamente.</p>'}}document.querySelectorAll('.service-option').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.service-option').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');service.value=btn.dataset.service;feedback.textContent='✓ '+btn.querySelector('span').textContent+' selecionado';feedback.classList.add('selected');loadSlots()});[barber,date].forEach(x=>x&&x.addEventListener('change',loadSlots));</script></body></html>
